// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAgentBudget An agent's daily limit (UTC day) and today's spend.
	// (GET /agents/{agentId}/budget)
	GetAgentBudget(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// SetAgentBudget Set an agent's daily limit. A template's spendUSD is only the default for a new agent.
	// (PUT /agents/{agentId}/budget)
	SetAgentBudget(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// GetAgentMcpServers The servers an agent may use.
	// (GET /agents/{agentId}/mcp-servers)
	GetAgentMcpServers(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// SetAgentMcpServers Replace the servers an agent may use, each optionally narrowed to some tools. Tools are
	// offered by tier; a tool the server adds later enters the ask tier for an agent that allows the
	// whole server.
	// (PUT /agents/{agentId}/mcp-servers)
	SetAgentMcpServers(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// GetAgentModel The model an agent's next run uses, and where that choice comes from.
	// (GET /agents/{agentId}/model)
	GetAgentModel(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// SetAgentModel Set an agent's model, or clear it with `default`.
	// (PUT /agents/{agentId}/model)
	SetAgentModel(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// SetAgentThinking Turn an agent's thinking on or off, or clear the setting.
	// (PUT /agents/{agentId}/thinking)
	SetAgentThinking(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID)
	// RunAgentTrigger Fire a schedule trigger now ("run now").
	// (POST /agents/{agentId}/triggers/{triggerId}/run)
	RunAgentTrigger(w http.ResponseWriter, r *http.Request, agentId openapi_types.UUID, triggerId string)
	// ListAuditEvents Read the org's audit log, newest first.
	// (GET /audit)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// ExportAudit Export an audit chain as JSON lines, verifiable off the cluster.
	// (GET /audit/export)
	ExportAudit(w http.ResponseWriter, r *http.Request, params ExportAuditParams)
	// GetBudget The org's monthly cap (calendar month, UTC), its platform ceiling and this month's spend.
	// (GET /budget)
	GetBudget(w http.ResponseWriter, r *http.Request)
	// SetBudget Set the org's monthly cap, or clear it by leaving `monthlyCapUsd` out.
	// (PUT /budget)
	SetBudget(w http.ResponseWriter, r *http.Request)
	// GetDefaultModel The org's default model, which agents without a model setting run on.
	// (GET /default-model)
	GetDefaultModel(w http.ResponseWriter, r *http.Request)
	// SetDefaultModel Set the org's default model, or clear it by leaving `model` out. Audited.
	// (PUT /default-model)
	SetDefaultModel(w http.ResponseWriter, r *http.Request)
	// GetHomeBackupRetention How long an old home backup repository is kept after a key change (issue
	// (GET /home-backup-retention)
	GetHomeBackupRetention(w http.ResponseWriter, r *http.Request)
	// SetHomeBackupRetention Set the retention in days, or return it to the default (7) by leaving `days` out. Audited.
	// (PUT /home-backup-retention)
	SetHomeBackupRetention(w http.ResponseWriter, r *http.Request)
	// GetLeakGuard The org's leak-guard settings, with defaults filled in, and its fetch-trusted host list.
	// (GET /leak-guard)
	GetLeakGuard(w http.ResponseWriter, r *http.Request)
	// SetLeakGuard Set the match threshold, or return it to the default by leaving `matchThreshold` out. Audited.
	// (PUT /leak-guard)
	SetLeakGuard(w http.ResponseWriter, r *http.Request)
	// AddFetchTrustedHost Put a host on the fetch-trusted list, which the automatic URL rule exempts. Audited.
	// (POST /leak-guard/trusted-hosts)
	AddFetchTrustedHost(w http.ResponseWriter, r *http.Request)
	// RemoveFetchTrustedHost Take a host off the fetch-trusted list. Audited.
	// (DELETE /leak-guard/trusted-hosts/{host})
	RemoveFetchTrustedHost(w http.ResponseWriter, r *http.Request, host string)
	// ListMcpServers List the org's remote MCP servers, entered and declared, with their health.
	// (GET /mcp-servers)
	ListMcpServers(w http.ResponseWriter, r *http.Request)
	// CreateMcpServer Add a remote MCP server. A server that asks each user to sign in with OAuth is refused (planned
	// for v0.2).
	// (POST /mcp-servers)
	CreateMcpServer(w http.ResponseWriter, r *http.Request)
	// DeleteMcpServer Delete a server, its tools and the agents' allowances of it. Declared servers answer 409.
	// (DELETE /mcp-servers/{serverId})
	DeleteMcpServer(w http.ResponseWriter, r *http.Request, serverId ServerId)
	// GetMcpServer Get a server.
	// (GET /mcp-servers/{serverId})
	GetMcpServer(w http.ResponseWriter, r *http.Request, serverId ServerId)
	// UpdateMcpServer Change a server's URL, transport or credential. Declared servers answer 409.
	// (PATCH /mcp-servers/{serverId})
	UpdateMcpServer(w http.ResponseWriter, r *http.Request, serverId ServerId)
	// SetMcpServerDataClass Set what a server exposes, its kind and the legs of the leak guard it carries. Audited.
	// (PUT /mcp-servers/{serverId}/data-class)
	SetMcpServerDataClass(w http.ResponseWriter, r *http.Request, serverId ServerId)
	// ListMcpTools The server's tools with their tiers and review flags.
	// (GET /mcp-servers/{serverId}/tools)
	ListMcpTools(w http.ResponseWriter, r *http.Request, serverId ServerId)
	// AcknowledgeMcpToolReview Mark a changed tool as reviewed without changing its tier.
	// (POST /mcp-servers/{serverId}/tools/{toolName}/review)
	AcknowledgeMcpToolReview(w http.ResponseWriter, r *http.Request, serverId ServerId, toolName ToolName)
	// SetMcpToolSink Declare a tool's sink class, its address arguments and what its results carry. Audited.
	// (PUT /mcp-servers/{serverId}/tools/{toolName}/sink)
	SetMcpToolSink(w http.ResponseWriter, r *http.Request, serverId ServerId, toolName ToolName)
	// SetMcpToolTier Move a tool to a tier: `ask` (a human approves each call), `auto` (the agent calls it) or
	// `never`. Works on declared servers too. Clears the tool's review flag.
	// (PUT /mcp-servers/{serverId}/tools/{toolName}/tier)
	SetMcpToolTier(w http.ResponseWriter, r *http.Request, serverId ServerId, toolName ToolName)
	// SetMcpToolTwoApprovers Require two approvers for calls to a tool in the ask tier: distinct admins or owners, neither the
	// ticket's creator. Off by default.
	// (PUT /mcp-servers/{serverId}/tools/{toolName}/two-approvers)
	SetMcpToolTwoApprovers(w http.ResponseWriter, r *http.Request, serverId ServerId, toolName ToolName)
	// ListModels List the org's models, entered and declared.
	// (GET /models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// CreateModel Add a model to a provider. Its price is an org price or a default one.
	// (POST /models)
	CreateModel(w http.ResponseWriter, r *http.Request)
	// DeleteModel Delete a model. Declared models answer 409.
	// (DELETE /models/{modelId})
	DeleteModel(w http.ResponseWriter, r *http.Request, modelId ModelId)
	// GetModel Get a model.
	// (GET /models/{modelId})
	GetModel(w http.ResponseWriter, r *http.Request, modelId ModelId)
	// UpdateModel Change a model's routing guard. Declared models answer 409.
	// (PATCH /models/{modelId})
	UpdateModel(w http.ResponseWriter, r *http.Request, modelId ModelId)
	// SetOutwardTargetDisabled Switch one outward target off or on. Audited as outward.disable or outward.enable.
	// (PUT /outward-targets/{kind}/{targetId}/disabled)
	SetOutwardTargetDisabled(w http.ResponseWriter, r *http.Request, kind OutwardTargetKind, targetId openapi_types.UUID)
	// ListPrices List the org's own prices, every version, newest first per name.
	// (GET /prices)
	ListPrices(w http.ResponseWriter, r *http.Request)
	// SetPrice Add a version of a named price. Earlier versions never change.
	// (POST /prices)
	SetPrice(w http.ResponseWriter, r *http.Request)
	// GetDefaultPrices The default price list this installation runs and the versions before it.
	// (GET /prices/defaults)
	GetDefaultPrices(w http.ResponseWriter, r *http.Request)
	// GetDefaultPriceChanges What changed in the default price list between two versions (after an upgrade).
	// (GET /prices/defaults/changes)
	GetDefaultPriceChanges(w http.ResponseWriter, r *http.Request, params GetDefaultPriceChangesParams)
	// ListFlaggedPrices Price entries whose recomputed cost differs from the gateway's by more than 1%.
	// (GET /prices/flagged)
	ListFlaggedPrices(w http.ResponseWriter, r *http.Request, params ListFlaggedPricesParams)
	// RetirePrice End a named price now. Its versions stay for the ledger entries that cite them.
	// (DELETE /prices/{name})
	RetirePrice(w http.ResponseWriter, r *http.Request, name string)
	// ListProviders List the org's providers, entered and declared.
	// (GET /providers)
	ListProviders(w http.ResponseWriter, r *http.Request)
	// CreateProvider Add a provider.
	// (POST /providers)
	CreateProvider(w http.ResponseWriter, r *http.Request)
	// DeleteProvider Delete a provider and its models. Declared providers answer 409.
	// (DELETE /providers/{providerId})
	DeleteProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// GetProvider Get a provider.
	// (GET /providers/{providerId})
	GetProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// UpdateProvider Change a provider's type, URL or key. Declared providers answer 409.
	// (PATCH /providers/{providerId})
	UpdateProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// CheckProviderEcho Check whether the provider changes the text it is sent.
	// (POST /providers/{providerId}/echo-check)
	CheckProviderEcho(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// GetRunContentRetention How long a finished run's stored content is kept (issue
	// (GET /run-content-retention)
	GetRunContentRetention(w http.ResponseWriter, r *http.Request)
	// SetRunContentRetention Set the retention in days, or return it to the default (30) by leaving `days` out. Audited.
	// (PUT /run-content-retention)
	SetRunContentRetention(w http.ResponseWriter, r *http.Request)
	// GetSpendReport Spend per model, with estimated usage shown apart from reported usage.
	// (GET /spend)
	GetSpendReport(w http.ResponseWriter, r *http.Request, params GetSpendReportParams)
	// ListTokens List the org's API tokens, newest first.
	// (GET /tokens)
	ListTokens(w http.ResponseWriter, r *http.Request)
	// CreateToken Create an API token. The secret is shown once.
	// (POST /tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)
	// RevokeToken Revoke a token. Revoking twice is fine.
	// (DELETE /tokens/{tokenId})
	RevokeToken(w http.ResponseWriter, r *http.Request, tokenId TokenId)
}

